<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFail;

class TrustedClientDynamicallyRegisteredVO
{
    public static function empty(): TrustedClientDynamicallyRegisteredVO
    {
        return new TrustedClientDynamicallyRegisteredVO(null);
    }
    public static function from(TrustedClientDynamicallyRegisteredVO|bool|null $value): TrustedClientDynamicallyRegisteredVO
    {
        return self::fromUnsafe($value);
    }
    public static function tryFrom(mixed $value, ConstraintFailList $list): ?TrustedClientDynamicallyRegisteredVO
    {
        if ($value instanceof TrustedClientDynamicallyRegisteredVO) {
            // If is a ValueObject, its already validated... nothing to append
            return $value;
        } elseif (!$value) {
            return new TrustedClientDynamicallyRegisteredVO($value);
        } elseif (is_bool($value)) {
            return new TrustedClientDynamicallyRegisteredVO($value);
        } else {
            $list->add(new ConstraintFail('wrong_type', ['dynamicallyRegistered'], [$value], ['bool']));
            return null;
        }
    }
    private static function fromUnsafe(mixed $value): TrustedClientDynamicallyRegisteredVO
    {
        if ($value instanceof TrustedClientDynamicallyRegisteredVO) {
            // If is a ValueObject, its already validated
            return $value;
        } else {
            // If is not a ValueObject, validation is need and exception throw
            $errorsList = new ConstraintFailList();
            $candidate = self::tryFrom($value, $errorsList);
            if ($errorsList->hasErrors()) {
                throw $errorsList->asConstraintException();
            }
            \assert($candidate instanceof TrustedClientDynamicallyRegisteredVO);
            return $candidate;
        }
    }
    /**
     * private constructor to avoid build a value without all the rule validations.
     */
    private function __construct(
        private readonly ?bool $dynamicallyRegistered
    ) {
    }
    public function value(): ?bool
    {
        return $this->dynamicallyRegistered;
    }
    public function equals(?TrustedClientDynamicallyRegisteredVO $other): bool
    {
        return $this->value() == $other?->value();
    }
}
